---@class MonthSignSubsystem
MonthSignSubsystem = class("MonthSignSubsystem")

function MonthSignSubsystem:initialize(...)
    NetResponseEventManager:Get():AddListener(MsgID.MONTH_SIGN_S2C_RET, self, self.RecvMsg_GetMonthSignList)
    NetResponseEventManager:Get():AddListener(MsgID.RETROACTIVE_MONTH_SIGN_S2C_RET, self, self.RecvMsg_RetroactiveMonthSign)

    --501,--返回观影幸运转盘
    NetResponseEventManager:Get():AddListener(MsgID.RET_VIDEO_LUCK, self, self.RecvMsg_RetVideoLuck)
    --503,--返回观影幸运转盘播放开始
    NetResponseEventManager:Get():AddListener(MsgID.RET_PLAY_VIDEO_LUCK, self, self.RecvMsg_RetPlayVideoLuck)
    --505,--返回观影幸运转盘播放结束发货
    NetResponseEventManager:Get():AddListener(MsgID.RET_FIN_VIDEO_LUCK, self, self.RecvMsg_RetFinVideoLuck)
    --507,--返回观影幸运转盘
    NetResponseEventManager:Get():AddListener(MsgID.RET_VIDEO_LUCKY_TABLE, self, self.RecvMsg_RetVideoLuckyTable)

    --509,--返回每日观影
    NetResponseEventManager:Get():AddListener(MsgID.RET_DAY_VIDEO, self, self.RecvMsg_RetDayVideo)
    --511,--返回每日观影播放开始
    NetResponseEventManager:Get():AddListener(MsgID.RET_DAY_VIDEO_PLAY, self, self.RecvMsg_RetDayVideoPlay)
    --513,--返回每日观影播放结束
    NetResponseEventManager:Get():AddListener(MsgID.RET_SUCC_DAY_VIDEO, self, self.RecvMsg_RetSuccDayVideo)
    --515,--返回每日观影奖励
    NetResponseEventManager:Get():AddListener(MsgID.RET_DAY_VIDEO_GIFT, self, self.RecvMsg_RetDayVideoGift)

end

function MonthSignSubsystem:SendMsg_GetMonthSignList()
    local reqData = CommonHelper:GetNetSendData({ PlayerDataManager:Get():GetPlayerRID() })
    NetManager:Get():Send(MsgID.MONTH_SIGN_C2S_REQ, reqData)
end

function MonthSignSubsystem:RecvMsg_GetMonthSignList(data)
    ---@type SC_UserMonthSign
    local msg = assert(Dll_PB.decode("UserMonthSign", data))
    log(ProtoMsgHelp.block(msg))
    MonthSignManager:Get():OnInit(msg)
end

---@param day number
---@param type number  @ 0正常签到  1是补签
function MonthSignSubsystem:SendMsg_RetroactiveMonthSign(day, type)
    local reqData = CommonHelper:GetNetSendData({ PlayerDataManager:Get():GetPlayerRID(), day, type })
    NetManager:Get():Send(MsgID.RETROACTIVE_MONTH_SIGN_C2S_REQ, reqData)
end

function MonthSignSubsystem:RecvMsg_RetroactiveMonthSign(data)
    ---@type SC_UserMonthSignAct
    local msg = assert(Dll_PB.decode("UserMonthSignAct", data))
    log(ProtoMsgHelp.block(msg))
    MonthSignManager:Get():UpdateData(msg.curSignInfo)
    PlayerDataManager:Get():SetRetroactiveMonthSign(msg.monthSign)
    if msg.curConsume then
        KnapsackDataManager:Get():UpdatePropByConsume(msg.curConsume)
    end
    if msg.mySomeDown and #msg.mySomeDown > 0 then
        CommonHelper:ShowGetRewardDataBySomeDown(msg.mySomeDown[1], true)
    end
    UINotify:Get():SendNotification(UINotifyEvent.WelfareVideoRefreshBtn)
end

