--507, --返回观影幸运转盘
function MonthSignSubsystem:RecvMsg_RetVideoLuckyTable(data)
    ---@type SC_VideoLuckTable
    local msg = assert(Dll_PB.decode("VideoLuckTable", data))
    log(ProtoMsgHelp.block(msg))

    if msg.curConsume then
        KnapsackDataManager:Get():UpdatePropByConsume(msg.curConsume)
    end

    local delayAwardShow = function()
        if msg.mySomeDown and #msg.mySomeDown > 0 then
            CommonHelper:ShowGetRewardDataBySomeDown(msg.mySomeDown[1], true)
        end
    end

    WelfareVideoDataManager:Get():InitLuckyTableStateData(msg)
    WelfareVideoDataManager:Get():InitLuckyTableStateData(msg)

    UINotify:Get():SendNotification(UINotifyEvent.WelfareVideo_PageRunAction,
            { WelfareFuncType.luckyTable, "RetLuckyTable", delayAwardShow, msg.hitSeq })

    UINotify:Get():SendNotification(UINotifyEvent.WelfareVideo_PageRunAction,
            { WelfareFuncType.luckyTable, "RefreshView" })
end

